CREATE SCHEMA IF NOT EXISTS report_private;
CREATE SCHEMA IF NOT EXISTS report_data;
REVOKE ALL ON SCHEMA report_private, report_data FROM PUBLIC, anon;
GRANT USAGE ON SCHEMA report_private, report_data TO authenticated;

CREATE TABLE report_private.sources (
 key text PRIMARY KEY, label text NOT NULL, module text NOT NULL, fields jsonb NOT NULL,
 date_field text, end_date_field text, employee_field text, center_field text,
 description text NOT NULL, version integer NOT NULL DEFAULT 2, required_modules text[] NOT NULL DEFAULT '{}'
);
REVOKE ALL ON report_private.sources FROM PUBLIC, anon, authenticated;
GRANT SELECT ON report_private.sources TO authenticated;

CREATE FUNCTION report_private.module_permission(c uuid,m text,a text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.user_custom_roles u JOIN public.custom_roles r ON r.id=u.role_id WHERE u.user_id=auth.uid() AND r.is_active AND (r.company_id IS NULL OR r.company_id=c) AND (r.is_system OR EXISTS(SELECT 1 FROM public.role_permissions rp JOIN public.permissions p ON p.id=rp.permission_id JOIN public.modules mod ON mod.id=p.module_id WHERE rp.role_id=r.id AND mod.is_active AND mod.code=m AND p.action::text=a)))
$$;
REVOKE ALL ON FUNCTION report_private.module_permission(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION report_private.module_permission(uuid,text,text) TO authenticated;

CREATE FUNCTION report_private.allowed(c uuid,m text,a text DEFAULT 'view') RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT auth.uid() IS NOT NULL
 AND (public.is_super_admin() OR public.is_company_member(c))
 AND (public.is_super_admin() OR EXISTS(SELECT 1 FROM public.user_preferences p WHERE p.user_id=auth.uid() AND p.ai_data_assistant_enabled))
 AND (public.is_super_admin() OR public.is_admin() OR report_private.module_permission(c,'asistente_ia','view'))
 AND (public.is_super_admin() OR public.is_admin() OR report_private.module_permission(c,m,a))
$$;
REVOKE ALL ON FUNCTION report_private.allowed(uuid,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION report_private.allowed(uuid,text,text) TO authenticated;

CREATE FUNCTION report_private.source_allowed(c uuid,s text,a text DEFAULT 'view') RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce((SELECT report_private.allowed(c,src.module,a) AND NOT EXISTS(SELECT 1 FROM unnest(src.required_modules) m WHERE NOT report_private.allowed(c,m,a)) FROM report_private.sources src WHERE src.key=s),false)
$$;
REVOKE ALL ON FUNCTION report_private.source_allowed(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION report_private.source_allowed(uuid,text,text) TO authenticated;

CREATE FUNCTION report_private.fingerprint(c uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT md5(jsonb_build_object('user',auth.uid(),'company',c,'admin',public.is_admin(),'super',public.is_super_admin(),
 'enabled',report_private.allowed(c,'asistente_ia','view'),
 'permissions',(SELECT jsonb_agg(p ORDER BY p.module_code,p.action) FROM public.get_user_permissions(auth.uid()) p),
 'centers',(SELECT jsonb_agg(uca.operation_center_id ORDER BY uca.operation_center_id) FROM public.user_center_assignments uca JOIN public.operation_centers oc ON oc.id=uca.operation_center_id WHERE uca.user_id=auth.uid() AND oc.company_id=c),
 'roles',(SELECT jsonb_agg(ur.role ORDER BY ur.role) FROM public.user_roles ur WHERE ur.user_id=auth.uid()),
 'scoped_roles',(SELECT jsonb_agg(jsonb_build_object('role',r.id,'company',r.company_id,'active',r.is_active,'system',r.is_system,'permissions',(SELECT jsonb_agg(rp.permission_id ORDER BY rp.permission_id) FROM public.role_permissions rp WHERE rp.role_id=r.id)) ORDER BY r.id) FROM public.user_custom_roles u JOIN public.custom_roles r ON r.id=u.role_id WHERE u.user_id=auth.uid()),
 'employee_scope',(SELECT md5(coalesce(string_agg(e.id::text,',' ORDER BY e.id),'')) FROM public.employees_v2 e WHERE e.company_id=c AND public.has_employee_v2_access(e.id)),
 'center_history',(SELECT md5(coalesce(string_agg(w.id::text||coalesce(w.operation_center_id::text,'')||w.is_current::text||coalesce(w.valid_to::text,''),',' ORDER BY w.id),'')) FROM public.employee_work_info w WHERE w.company_id=c),
 'catalog',(SELECT sum(version) FROM report_private.sources))::text)
$$;
REVOKE ALL ON FUNCTION report_private.fingerprint(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION report_private.fingerprint(uuid) TO authenticated;

CREATE TABLE report_private.runs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id),
 user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, parent_id uuid REFERENCES report_private.runs(id),
 title text NOT NULL, question text NOT NULL, context jsonb NOT NULL DEFAULT '[]', plan jsonb NOT NULL,
 filters jsonb NOT NULL, result jsonb NOT NULL, fingerprint text NOT NULL,
 provider text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX report_runs_owner ON report_private.runs(company_id,user_id,created_at DESC);
CREATE TABLE report_private.favorites (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),
 user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,title text NOT NULL,
 question text NOT NULL,context jsonb NOT NULL DEFAULT '[]',filters jsonb NOT NULL DEFAULT '{}',
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX report_favorites_owner ON report_private.favorites(company_id,user_id,created_at DESC);
CREATE UNIQUE INDEX report_favorites_definition ON report_private.favorites(company_id,user_id,md5(question||context::text||filters::text));
ALTER TABLE report_private.runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE report_private.favorites ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON report_private.runs,report_private.favorites FROM PUBLIC,anon,authenticated;

CREATE FUNCTION report_private.field(s text,k text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE f jsonb;
BEGIN
 SELECT e INTO f FROM report_private.sources src CROSS JOIN LATERAL jsonb_array_elements(src.fields) e WHERE src.key=s AND e->>'key'=k;
 IF f IS NULL THEN RAISE EXCEPTION 'INVALID_FIELD: Campo no autorizado'; END IF;
 IF f ? 'permission' AND NOT (public.is_admin() OR public.is_super_admin() OR public.check_user_permission(auth.uid(),f->>'permission','view')) THEN RAISE EXCEPTION 'FORBIDDEN: Campo restringido'; END IF;
 RETURN f;
END $$;

CREATE FUNCTION report_private.filters(s text,fs jsonb,alias_name text DEFAULT 'b') RETURNS text
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE f jsonb; col jsonb; val text; expr text; out_sql text:=''; op text; typed text; v jsonb;
BEGIN
 IF jsonb_typeof(fs)<>'array' OR jsonb_array_length(fs)>20 THEN RAISE EXCEPTION 'INVALID_PLAN: Filtros inválidos'; END IF;
 FOR f IN SELECT * FROM jsonb_array_elements(fs) LOOP
   col:=report_private.field(s,f->>'field'); op:=f->>'op';
   expr:=format('%I.%I',alias_name,f->>'field');
   IF op IN ('is_null','not_null') THEN
     out_sql:=out_sql||format(' AND %s IS %sNULL',expr,CASE WHEN op='not_null' THEN 'NOT ' ELSE '' END); CONTINUE;
   END IF;
   IF jsonb_typeof(f->'values')<>'array' OR jsonb_array_length(f->'values') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'INVALID_PLAN: Valores de filtro inválidos'; END IF;
   typed:='';
   FOR v IN SELECT * FROM jsonb_array_elements(f->'values') LOOP
     IF jsonb_typeof(v)<>'string' OR length(v#>>'{}')>500 THEN RAISE EXCEPTION 'INVALID_PLAN: Valor inválido'; END IF;
     val:=v#>>'{}';
     IF col->>'type'='number' THEN PERFORM val::numeric; END IF;
     IF col->>'type'='date' THEN PERFORM val::date; END IF;
     IF col->>'type'='datetime' THEN PERFORM val::timestamptz; END IF;
     IF col->>'type'='boolean' AND val NOT IN ('true','false') THEN RAISE EXCEPTION 'INVALID_PLAN: Booleano inválido'; END IF;
     typed:=typed||CASE WHEN typed<>'' THEN ',' ELSE '' END||format('%L',val);
   END LOOP;
   IF op='in' THEN out_sql:=out_sql||format(' AND %s IN (%s)',expr,typed);
   ELSIF op='contains' THEN
     IF col->>'type'<>'text' OR jsonb_array_length(f->'values')<>1 THEN RAISE EXCEPTION 'INVALID_PLAN: Búsqueda inválida'; END IF;
     out_sql:=out_sql||format(' AND strpos(lower(%s::text),lower(%L))>0',expr,f->'values'->>0);
   ELSE
     IF jsonb_array_length(f->'values')<>1 OR op NOT IN ('eq','neq','gt','gte','lt','lte') THEN RAISE EXCEPTION 'INVALID_PLAN: Operador inválido'; END IF;
     out_sql:=out_sql||format(' AND %s %s %s',expr,CASE op WHEN 'eq' THEN '=' WHEN 'neq' THEN '<>' WHEN 'gt' THEN '>' WHEN 'gte' THEN '>=' WHEN 'lt' THEN '<' ELSE '<=' END,typed);
   END IF;
 END LOOP;
 RETURN out_sql;
END $$;

CREATE FUNCTION report_private.query(c uuid,p jsonb,screen jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' SET timezone='America/Bogota' SET statement_timeout='15s' AS $$
DECLARE s report_private.sources; related_source report_private.sources; f jsonb; meta jsonb; k text; expression text;
 select_sql text:=''; group_sql text:=''; where_sql text; order_sql text:=''; columns_json jsonb:='[]';
 result_rows jsonb; outputs text[]:='{}'; refs text[]:='{}'; total bigint; cast_date text; limiting integer;
BEGIN
 IF auth.uid() IS NULL OR NOT report_private.allowed(c,'asistente_ia','view') THEN RAISE EXCEPTION 'FORBIDDEN: Asistente no autorizado'; END IF;
 IF NOT (p ?& ARRAY['source','columns','dimensions','metrics','filters','related','order','chart','limit','comparePrevious']) OR jsonb_typeof(p->'comparePrevious') IS DISTINCT FROM 'boolean' OR p->>'chart' NOT IN ('bar','line','donut','none') THEN RAISE EXCEPTION 'INVALID_PLAN: Plan incompleto'; END IF;
 IF jsonb_typeof(screen) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(screen) sk(key) WHERE sk.key NOT IN ('startDate','endDate','centerIds')) THEN RAISE EXCEPTION 'INVALID_PLAN: Filtros de pantalla inválidos'; END IF;
 IF screen->>'startDate' IS NOT NULL AND screen->>'endDate' IS NOT NULL AND (screen->>'startDate')::date>(screen->>'endDate')::date THEN RAISE EXCEPTION 'INVALID_PLAN: Periodo invertido'; END IF;
 IF screen ? 'centerIds' THEN
  IF jsonb_typeof(screen->'centerIds') IS DISTINCT FROM 'array' OR jsonb_array_length(screen->'centerIds')>200 THEN RAISE EXCEPTION 'INVALID_PLAN: Centros inválidos'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(screen->'centerIds') cid WHERE NOT EXISTS(SELECT 1 FROM public.operation_centers oc WHERE oc.id=cid::uuid AND oc.company_id=c AND public.check_center_access(c,oc.id))) THEN RAISE EXCEPTION 'FORBIDDEN: Centro no autorizado'; END IF;
 END IF;
 IF jsonb_typeof(p)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p) a WHERE a NOT IN ('source','columns','dimensions','metrics','filters','related','order','chart','limit','comparePrevious')) THEN RAISE EXCEPTION 'INVALID_PLAN: Plan inválido'; END IF;
 SELECT * INTO s FROM report_private.sources WHERE key=p->>'source';
 IF s.key IS NULL OR NOT report_private.source_allowed(c,s.key,'view') THEN RAISE EXCEPTION 'FORBIDDEN: Fuente no autorizada'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(s.fields) sf WHERE sf ? 'permission' AND strpos(p::text,'"'||(sf->>'key')||'"')>0 AND NOT report_private.allowed(c,sf->>'permission','view')) THEN RAISE EXCEPTION 'FORBIDDEN: Campo restringido en esta empresa'; END IF;
 refs:=array_append(refs,s.key);
 IF s.key='training_compliance' AND (screen->>'startDate' IS NULL OR screen->>'endDate' IS NULL) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'filters') pf(value) WHERE pf.value->>'field'='period') THEN RAISE EXCEPTION 'CLARIFICATION: Define un periodo de capacitación'; END IF;
 IF jsonb_typeof(p->'columns')<>'array' OR jsonb_array_length(p->'columns')>30 OR jsonb_typeof(p->'metrics')<>'array' OR jsonb_array_length(p->'metrics')>12 OR jsonb_typeof(p->'dimensions')<>'array' OR jsonb_array_length(p->'dimensions')>5 OR jsonb_typeof(p->'related')<>'array' OR jsonb_array_length(p->'related')>5 OR jsonb_typeof(p->'order')<>'array' OR jsonb_array_length(p->'order')>5 THEN RAISE EXCEPTION 'INVALID_PLAN: Estructura inválida'; END IF;
 IF jsonb_array_length(p->'metrics')>0 AND jsonb_array_length(p->'columns')>0 THEN RAISE EXCEPTION 'INVALID_PLAN: Mezcla de detalle y agregación'; END IF;
 IF jsonb_array_length(p->'metrics')=0 AND jsonb_array_length(p->'dimensions')>0 THEN RAISE EXCEPTION 'INVALID_PLAN: Agrupación sin métricas'; END IF;
 FOR f IN SELECT * FROM jsonb_array_elements(p->'columns') LOOP
   k:=f#>>'{}';meta:=report_private.field(s.key,k);
   select_sql:=select_sql||CASE WHEN select_sql<>'' THEN ',' ELSE '' END||format('b.%I',k);
   columns_json:=columns_json||jsonb_build_array(meta);outputs:=array_append(outputs,k);
 END LOOP;
 FOR f IN SELECT * FROM jsonb_array_elements(p->'dimensions') LOOP
   k:=f->>'field';meta:=report_private.field(s.key,k);expression:=format('b.%I',k);
   IF f->>'grain' NOT IN ('value','day','month','year') THEN RAISE EXCEPTION 'INVALID_PLAN: Periodo inválido'; END IF;
   IF f->>'grain'<>'value' THEN
     IF meta->>'type' NOT IN ('date','datetime') THEN RAISE EXCEPTION 'INVALID_PLAN: Fecha requerida'; END IF;
     expression:=format('date_trunc(%L,%s)::date',f->>'grain',expression);meta:=jsonb_set(meta,'{type}','"date"');
   END IF;
   select_sql:=select_sql||CASE WHEN select_sql<>'' THEN ',' ELSE '' END||format('%s AS %I',expression,k);
   group_sql:=group_sql||CASE WHEN group_sql<>'' THEN ',' ELSE '' END||expression;
   columns_json:=columns_json||jsonb_build_array(meta);outputs:=array_append(outputs,k);
 END LOOP;
 FOR f IN SELECT * FROM jsonb_array_elements(p->'metrics') LOOP
   k:=f->>'key';
   IF k!~'^[a-z][a-z0-9_]{0,49}$' OR f->>'op' NOT IN ('count','distinct','sum','avg','min','max') THEN RAISE EXCEPTION 'INVALID_PLAN: Métrica inválida'; END IF;
   IF f->>'field'='*' THEN
     IF f->>'op'<>'count' THEN RAISE EXCEPTION 'INVALID_PLAN: Campo requerido'; END IF;
     expression:='count(*)';meta:=jsonb_build_object('label','Registros','type','number');
   ELSE
     meta:=report_private.field(s.key,f->>'field');
     IF f->>'op' IN ('sum','avg') AND meta->>'type'<>'number' THEN RAISE EXCEPTION 'INVALID_PLAN: Número requerido'; END IF;
     expression:=CASE WHEN f->>'op'='distinct' THEN format('count(DISTINCT b.%I)',f->>'field') ELSE format('%s(b.%I)',f->>'op',f->>'field') END;
     meta:=meta||jsonb_build_object('label',CASE f->>'op' WHEN 'sum' THEN 'Total · ' WHEN 'avg' THEN 'Promedio · ' WHEN 'min' THEN 'Mínimo · ' WHEN 'max' THEN 'Máximo · ' ELSE 'Cantidad · ' END||(meta->>'label'));
     IF f->>'op' IN ('count','distinct') THEN meta:=(meta-'unit')||jsonb_build_object('type','number'); END IF;
   END IF;
   select_sql:=select_sql||CASE WHEN select_sql<>'' THEN ',' ELSE '' END||format('%s AS %I',expression,k);
   columns_json:=columns_json||jsonb_build_array(meta||jsonb_build_object('key',k));outputs:=array_append(outputs,k);
 END LOOP;
 IF select_sql='' OR cardinality(outputs)<>(SELECT count(DISTINCT x) FROM unnest(outputs) x) THEN RAISE EXCEPTION 'INVALID_PLAN: Columnas vacías o duplicadas'; END IF;
 where_sql:=format(CASE WHEN s.key IN ('catalog_eps','catalog_afp','catalog_arl','catalog_ccf','catalog_afc','catalog_ips','catalog_banks','identification_types','education_levels','professions','company_holidays','contract_type_config','novelty_reasons','dotation_item_types','exam_catalog') THEN '(b.company_id=%L::uuid OR b.company_id IS NULL)' ELSE 'b.company_id=%L::uuid' END,c)||report_private.filters(s.key,p->'filters');
 IF screen->>'startDate' IS NOT NULL OR screen->>'endDate' IS NOT NULL THEN
   IF s.date_field IS NULL THEN RAISE EXCEPTION 'CLARIFICATION: Esta fuente no tiene fecha; elimina el filtro de periodo'; END IF;
   IF screen->>'startDate' IS NOT NULL THEN
     PERFORM (screen->>'startDate')::date;
     where_sql:=where_sql||format(' AND b.%I::date >= %L::date',coalesce(s.end_date_field,s.date_field),screen->>'startDate');
   END IF;
   IF screen->>'endDate' IS NOT NULL THEN
     PERFORM (screen->>'endDate')::date;
     where_sql:=where_sql||format(' AND b.%I::date <= %L::date',s.date_field,screen->>'endDate');
   END IF;
 END IF;
 IF jsonb_array_length(coalesce(screen->'centerIds','[]'))>0 THEN
   IF s.center_field IS NULL THEN RAISE EXCEPTION 'CLARIFICATION: Esta fuente es general; elimina el filtro de centros'; END IF;
   where_sql:=where_sql||format(' AND b.%I IN (SELECT value::uuid FROM jsonb_array_elements_text(%L::jsonb))',s.center_field,(screen->'centerIds')::text);
 END IF;
 FOR f IN SELECT * FROM jsonb_array_elements(p->'related') LOOP
   SELECT * INTO related_source FROM report_private.sources WHERE key=f->>'source';
   IF related_source.key IS NULL OR s.employee_field IS NULL OR related_source.employee_field IS NULL OR NOT report_private.source_allowed(c,related_source.key,'view') THEN RAISE EXCEPTION 'FORBIDDEN: Cruce no autorizado'; END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(related_source.fields) sf WHERE sf ? 'permission' AND strpos(f::text,'"'||(sf->>'key')||'"')>0 AND NOT report_private.allowed(c,sf->>'permission','view')) THEN RAISE EXCEPTION 'FORBIDDEN: Campo restringido en el cruce'; END IF;
   IF f->>'mode' NOT IN ('exists','not_exists') THEN RAISE EXCEPTION 'INVALID_PLAN: Cruce inválido'; END IF;
   refs:=array_append(refs,related_source.key);
   where_sql:=where_sql||format(' AND %s EXISTS(SELECT 1 FROM report_data.%I r WHERE r.company_id=%L::uuid AND r.%I=b.%I %s)',CASE WHEN f->>'mode'='not_exists' THEN 'NOT' ELSE '' END,related_source.key,c,related_source.employee_field,s.employee_field,report_private.filters(related_source.key,f->'filters','r'));
 END LOOP;
 FOR f IN SELECT * FROM jsonb_array_elements(p->'order') LOOP
   IF NOT (f->>'field'=ANY(outputs)) OR f->>'direction' NOT IN ('asc','desc') THEN RAISE EXCEPTION 'INVALID_PLAN: Orden inválido'; END IF;
   order_sql:=order_sql||CASE WHEN order_sql<>'' THEN ',' ELSE '' END||format('%I %s NULLS LAST',f->>'field',f->>'direction');
 END LOOP;
 -- A complete deterministic result is stored once; pagination/export never rerun offset queries.
 IF order_sql='' THEN order_sql:=format('%I',outputs[1]); END IF;
 IF p->>'limit' IS NOT NULL THEN limiting:=(p->>'limit')::integer; IF limiting NOT BETWEEN 1 AND 50000 THEN RAISE EXCEPTION 'INVALID_PLAN: Límite inválido'; END IF; END IF;
 EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(q)),''[]''::jsonb) FROM (SELECT %s FROM report_data.%I b WHERE %s %s ORDER BY %s LIMIT %s) q',select_sql,s.key,where_sql,CASE WHEN group_sql<>'' THEN ' GROUP BY '||group_sql ELSE '' END,order_sql,coalesce(limiting,50001)) INTO result_rows;
 total:=jsonb_array_length(result_rows);
 IF total>50000 OR pg_column_size(result_rows)>16777216 THEN RAISE EXCEPTION 'RESULT_TOO_LARGE: Más de 50.000 filas o 16 MB. Acota el periodo o utiliza una agrupación'; END IF;
 RETURN jsonb_build_object('columns',columns_json,'rows',result_rows,'totalRows',total,'sourceKeys',refs);
END $$;

REVOKE ALL ON FUNCTION report_private.field(text,text),report_private.filters(text,jsonb,text),report_private.query(uuid,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION report_private.field(text,text),report_private.filters(text,jsonb,text),report_private.query(uuid,jsonb,jsonb) TO authenticated;




CREATE OR REPLACE VIEW report_data.employees_v2 WITH (security_invoker=true,security_barrier=true) AS SELECT b."birth_city",b."birth_country",b."birth_date",b."birth_department",b."blood_type",b."created_at",b."created_by",b."disability_type",b."document_issue_city",b."document_issue_date",b."document_number",b."document_type",b."education_level_id",b."ethnic_group",b."first_name",b."gender",b."gender_identity",b."gender_identity_other",b."id",b."identification_type_id",b."is_active",b."is_conflict_victim",b."is_demobilized",b."is_first_job",b."is_head_of_household",b."last_name",b."marital_status",b."middle_name",b."proceso_exclusivo_pcd",b."profession_id",b."second_last_name",b."status",b."updated_at",b.company_id,b.id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,w.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=w.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.employees_v2 b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.id AND w.company_id=b.company_id AND w.is_current ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'empleados', 'view') AND (b.id IS NULL OR public.has_employee_v2_access(b.id)) AND public.check_center_access(b.company_id,w.operation_center_id);
CREATE OR REPLACE VIEW report_data.employee_employment_cycles WITH (security_invoker=true,security_barrier=true) AS SELECT b."candidate_id",b."created_at",b."created_by",b."cycle_number",b."employee_id",b."end_date",b."id",b."source",b."start_date",b."status",b."updated_at",b.company_id,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,w.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=w.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.employee_employment_cycles b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND w.valid_from<=b.start_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.start_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'empleados', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,w.operation_center_id);
CREATE OR REPLACE VIEW report_data.employee_work_info WITH (security_invoker=true,security_barrier=true) AS SELECT b."area_id",b."cost_center",b."created_at",b."created_by",b."employee_id",b."employment_cycle_id",b."hire_date",b."id",b."is_current",b."link_type",b."operation_center_id",b."position_id",b."position_name",b."termination_date",b."updated_at",b."valid_from",b."valid_to",b."work_city",b.company_id,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,COALESCE(b.operation_center_id,w.operation_center_id) AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=COALESCE(b.operation_center_id,w.operation_center_id) AND oc.company_id=b.company_id) AS report_center_name FROM public.employee_work_info b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND (b.employment_cycle_id IS NULL OR w.employment_cycle_id=b.employment_cycle_id) AND w.valid_from<=b.hire_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.hire_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'empleados', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,COALESCE(b.operation_center_id,w.operation_center_id));
