CREATE OR REPLACE VIEW report_data.contracts WITH (security_invoker=true,security_barrier=true) AS SELECT b."approved_at",b."approved_by",b."contract_number",b."contract_type",b."created_at",b."created_by",b."employee_id",b."employment_cycle_id",b."end_date",b."has_confidentiality_clause",b."has_non_compete_clause",b."id",b."is_approved",b."is_terminated",b."other_allowances",b."salary",b."salary_type",b."special_clauses",b."start_date",b."termination_date",b."termination_reason",b."transport_allowance",b."trial_end_date",b."trial_period_days",b."updated_at",b."work_address",b."work_city",b."work_labor_description",b.company_id,greatest(b.end_date,(SELECT max(x.end_date) FROM public.contract_extensions x WHERE x.contract_id=b.id AND x.company_id=b.company_id)) AS effective_end_date,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,w.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=w.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.contracts b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND (b.employment_cycle_id IS NULL OR w.employment_cycle_id=b.employment_cycle_id) AND w.valid_from<=b.end_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.end_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'contratos', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,w.operation_center_id);
CREATE OR REPLACE VIEW report_data.contract_extensions WITH (security_invoker=true,security_barrier=true) AS SELECT b."contract_id",b."created_at",b."created_by",b."end_date",b."extension_number",b."extension_type",b."id",b."new_salary",b."start_date",b.company_id,(SELECT p.employee_id FROM public.contracts p WHERE p.id=b.contract_id AND p.company_id=b.company_id) AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,w.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=w.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.contract_extensions b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=(SELECT p.employee_id FROM public.contracts p WHERE p.id=b.contract_id AND p.company_id=b.company_id) AND w.company_id=b.company_id AND w.valid_from<=b.start_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.start_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=(SELECT p.employee_id FROM public.contracts p WHERE p.id=b.contract_id AND p.company_id=b.company_id) AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'contratos', 'view') AND ((SELECT p.employee_id FROM public.contracts p WHERE p.id=b.contract_id AND p.company_id=b.company_id) IS NULL OR public.has_employee_v2_access((SELECT p.employee_id FROM public.contracts p WHERE p.id=b.contract_id AND p.company_id=b.company_id))) AND public.check_center_access(b.company_id,w.operation_center_id);
CREATE OR REPLACE VIEW report_data.work_certificates WITH (security_invoker=true,security_barrier=true) AS SELECT b."consecutive",b."created_at",b."created_by",b."employee_id",b."folio",b."generation_type",b."id",b.company_id,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,w.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=w.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.work_certificates b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND w.valid_from<=b.created_at::date AND (w.valid_to IS NULL OR w.valid_to>=b.created_at::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'contratos', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,w.operation_center_id);
CREATE OR REPLACE VIEW report_data.employee_terminations WITH (security_invoker=true,security_barrier=true) AS SELECT b."completed_at",b."completed_by",b."contract_id",b."created_at",b."created_by",b."effective_date",b."employee_id",b."employment_cycle_id",b."id",b."is_completed",b."resignation_date",b."termination_date",b."termination_type",b."updated_at",b.company_id,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,w.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=w.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.employee_terminations b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND (b.employment_cycle_id IS NULL OR w.employment_cycle_id=b.employment_cycle_id) AND w.valid_from<=b.effective_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.effective_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'empleados', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,w.operation_center_id);
CREATE OR REPLACE VIEW report_data.termination_documents WITH (security_invoker=true,security_barrier=true) AS SELECT b."created_at",b."document_type",b."generated_at",b."generated_by",b."id",b."is_generated",b."is_required",b."is_signed",b."signed_at",b."signed_by",b."termination_id",b."updated_at",b.company_id,(SELECT p.employee_id FROM public.employee_terminations p WHERE p.id=b.termination_id AND p.company_id=b.company_id) AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,w.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=w.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.termination_documents b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=(SELECT p.employee_id FROM public.employee_terminations p WHERE p.id=b.termination_id AND p.company_id=b.company_id) AND w.company_id=b.company_id AND w.valid_from<=b.created_at::date AND (w.valid_to IS NULL OR w.valid_to>=b.created_at::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=(SELECT p.employee_id FROM public.employee_terminations p WHERE p.id=b.termination_id AND p.company_id=b.company_id) AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'empleados', 'view') AND ((SELECT p.employee_id FROM public.employee_terminations p WHERE p.id=b.termination_id AND p.company_id=b.company_id) IS NULL OR public.has_employee_v2_access((SELECT p.employee_id FROM public.employee_terminations p WHERE p.id=b.termination_id AND p.company_id=b.company_id))) AND public.check_center_access(b.company_id,w.operation_center_id);
CREATE OR REPLACE VIEW report_data.operation_centers WITH (security_invoker=true,security_barrier=true) AS SELECT b."address",b."city",b."code",b."contract_commercial_date",b."contract_start_date",b."created_at",b."created_by",b."department",b."id",b."is_active",b."main_client",b."manager_name",b."name",b."phone",b."updated_at",b.company_id,b.id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=b.id AND oc.company_id=b.company_id) AS report_center_name FROM public.operation_centers b WHERE report_private.allowed(b.company_id, 'centros', 'view') AND public.check_center_access(b.company_id,b.id);
