CREATE OR REPLACE VIEW report_data.positions WITH (security_invoker=true,security_barrier=true) AS SELECT b."area_id",b."code",b."created_at",b."created_by",b."id",b."is_active",b."level",b."max_salary",b."min_salary",b."name",b."parent_position_id",b."requirements",b."updated_at",b.company_id FROM public.positions b WHERE report_private.allowed(b.company_id, 'catalogos_cargos', 'view');
CREATE OR REPLACE VIEW report_data.position_profiles WITH (security_invoker=true,security_barrier=true) AS SELECT b."approved_by",b."created_at",b."created_by",b."education_detail",b."education_level",b."effective_date",b."elaborated_by",b."experience",b."id",b."is_current",b."num_positions",b."position_id",b."purpose",b."reports_to",b."reviewed_by",b."supervises",b."updated_at",b."version",b.company_id FROM public.position_profiles b WHERE report_private.allowed(b.company_id, 'catalogos_cargos', 'view');
CREATE OR REPLACE VIEW report_data.position_profile_annexes WITH (security_invoker=true,security_barrier=true) AS SELECT b."created_at",b."created_by",b."education_detail",b."education_level",b."experience",b."id",b."num_positions",b."operation_center_id",b."profile_id",b."purpose",b."reports_to",b."supervises",b."updated_at",b.company_id,b.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=b.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.position_profile_annexes b WHERE report_private.allowed(b.company_id, 'catalogos_cargos', 'view') AND public.check_center_access(b.company_id,b.operation_center_id);
CREATE OR REPLACE VIEW report_data.personnel_requisitions WITH (security_invoker=true,security_barrier=true) AS SELECT b."area_id",b."autoriza",b."cantidad_vacantes_requeridas",b."cargo_a_reemplazar",b."cargo_solicitado",b."cargo_solicitante",b."coordinadores_aprobado",b."coordinadores_aprobador_id",b."coordinadores_fecha_aprobacion",b."coordinadores_quien_aprobo",b."created_at",b."created_by",b."current_approval_step_id",b."dia_descanso_obligatorio",b."estado_requisicion",b."fecha_ingreso_estimada",b."fecha_requisicion",b."gerencia_aprobado",b."gerencia_aprobado_salario",b."gerencia_aprobador_id",b."gerencia_fecha_aprobacion",b."gerencia_quien_aprobo",b."horario_trabajo",b."id",b."incluye_alimentacion",b."incluye_desplazamiento",b."is_confidential",b."juridico_aprobado",b."juridico_aprobador_id",b."juridico_duracion",b."juridico_fecha_aprobacion",b."juridico_quien_aprobo",b."juridico_tipo_contrato",b."lider_proceso",b."motivo_solicitud",b."observaciones_motivo_solicitud",b."operaciones_aprobado",b."operaciones_aprobado_salario",b."operaciones_aprobador_id",b."operaciones_fecha_aprobacion",b."operaciones_quien_aprobo",b."operation_center_id",b."persona_a_reemplazar",b."proceso_exclusivo_pcd",b."requiere_herramienta_trabajo",b."requisition_code",b."rrhh_aprobado",b."rrhh_aprobador_id",b."rrhh_asignacion_salarial",b."rrhh_condiciones_adicionales",b."rrhh_fecha_aprobacion",b."rrhh_fuente_asignacion_salarial",b."rrhh_incluye_auxilio_transporte",b."rrhh_nivel_politica_salarial",b."rrhh_quien_aprobo",b."rrhh_tipo_convocatoria",b."salario_propuesto",b."seleccion_aprobado",b."seleccion_aprobador_id",b."seleccion_fecha_aprobacion",b."seleccion_fecha_inicio_proceso",b."seleccion_perfil_cargo_creado",b."seleccion_quien_aprobo",b."seleccion_tipo_mano_obra",b."solicitante_id",b."solicitante_nombre",b."tipo_contrato_solicitado",b."trayecto_desplazamiento",b."turno_trabajo_id",b."updated_at",b."workflow_version_id",b.company_id,b.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=b.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.personnel_requisitions b WHERE report_private.allowed(b.company_id, 'requisiciones', 'view') AND (NOT b.is_confidential OR report_private.allowed(b.company_id,'req_confidential_requisitions','view')) AND public.check_center_access(b.company_id,b.operation_center_id);
