CREATE OR REPLACE VIEW report_data.vacancies WITH (security_invoker=true,security_barrier=true) AS SELECT b."actual_close_date",b."cancellation_reason",b."cancelled_at",b."cancelled_by",b."created_at",b."created_by",b."department_area",b."education_level",b."education_level_id",b."experience_years",b."hiring_manager_id",b."id",b."includes_transport",b."job_description",b."open_date",b."operation_center_id",b."other_benefits",b."position_id",b."position_title",b."positions_count",b."priority",b."profession_id",b."psychologist_id",b."reason_details",b."requirements",b."requisition_id",b."salary_range_max",b."salary_range_min",b."salary_type",b."shift_type",b."status",b."target_close_date",b."updated_at",b."vacancy_reason",b."vacancy_type",b.company_id,b.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=b.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.vacancies b WHERE report_private.allowed(b.company_id, 'seleccion', 'view') AND public.check_center_access(b.company_id,b.operation_center_id);
CREATE OR REPLACE VIEW report_data.candidates WITH (security_invoker=true,security_barrier=true) AS SELECT b."address",b."application_date",b."birth_date",b."blood_type",b."city",b."created_at",b."created_by",b."current_company",b."current_position",b."current_step",b."department",b."disability_type",b."document_issue_city",b."document_issue_date",b."document_number",b."document_type",b."education_level",b."education_level_id",b."email",b."emergency_contact_name",b."emergency_contact_phone",b."emergency_contact_relationship",b."employee_id",b."ethnic_group",b."experience_years",b."final_concept",b."final_score",b."first_name",b."gender",b."gender_identity",b."gender_identity_other",b."id",b."identification_type_id",b."is_conflict_victim",b."is_demobilized",b."is_first_job",b."is_head_of_household",b."is_selected",b."last_name",b."marital_status",b."mobile",b."neighborhood",b."phone",b."profession",b."profession_id",b."rehire_employee_id",b."rejection_reason",b."salary_expectation",b."source",b."status",b."strengths",b."thanks_sent_at",b."updated_at",b."vacancy_id",b."weaknesses",b."withdrawal_reason",b.company_id,(SELECT v.operation_center_id FROM public.vacancies v WHERE v.id=b.vacancy_id AND v.company_id=b.company_id) AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=(SELECT v.operation_center_id FROM public.vacancies v WHERE v.id=b.vacancy_id AND v.company_id=b.company_id) AND oc.company_id=b.company_id) AS report_center_name FROM public.candidates b WHERE report_private.allowed(b.company_id, 'seleccion', 'view') AND public.check_center_access(b.company_id,(SELECT v.operation_center_id FROM public.vacancies v WHERE v.id=b.vacancy_id AND v.company_id=b.company_id));
CREATE OR REPLACE VIEW report_data.selection_steps WITH (security_invoker=true,security_barrier=true) AS SELECT b."candidate_id",b."completed_date",b."created_at",b."created_by",b."doctor_name",b."evaluator_id",b."evaluator_name",b."id",b."medical_concept",b."order_type",b."provider",b."result",b."scheduled_date",b."score",b."status",b."step_order",b."step_type",b."updated_at",b.company_id,(SELECT v.operation_center_id FROM public.candidates c JOIN public.vacancies v ON v.id=c.vacancy_id AND v.company_id=c.company_id WHERE c.id=b.candidate_id AND c.company_id=b.company_id) AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=(SELECT v.operation_center_id FROM public.candidates c JOIN public.vacancies v ON v.id=c.vacancy_id AND v.company_id=c.company_id WHERE c.id=b.candidate_id AND c.company_id=b.company_id) AND oc.company_id=b.company_id) AS report_center_name FROM public.selection_steps b WHERE report_private.allowed(b.company_id, 'seleccion', 'view') AND public.check_center_access(b.company_id,(SELECT v.operation_center_id FROM public.candidates c JOIN public.vacancies v ON v.id=c.vacancy_id AND v.company_id=c.company_id WHERE c.id=b.candidate_id AND c.company_id=b.company_id));
CREATE OR REPLACE VIEW report_data.candidate_documents WITH (security_invoker=true,security_barrier=true) AS SELECT b."candidate_id",b."created_at",b."document_name",b."document_type",b."expiry_date",b."file_name",b."file_size",b."id",b."mime_type",b."updated_at",b."uploaded_by",b.company_id,(SELECT v.operation_center_id FROM public.candidates c JOIN public.vacancies v ON v.id=c.vacancy_id AND v.company_id=c.company_id WHERE c.id=b.candidate_id AND c.company_id=b.company_id) AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=(SELECT v.operation_center_id FROM public.candidates c JOIN public.vacancies v ON v.id=c.vacancy_id AND v.company_id=c.company_id WHERE c.id=b.candidate_id AND c.company_id=b.company_id) AND oc.company_id=b.company_id) AS report_center_name FROM public.candidate_documents b WHERE report_private.allowed(b.company_id, 'seleccion', 'view') AND public.check_center_access(b.company_id,(SELECT v.operation_center_id FROM public.candidates c JOIN public.vacancies v ON v.id=c.vacancy_id AND v.company_id=c.company_id WHERE c.id=b.candidate_id AND c.company_id=b.company_id));
