CREATE OR REPLACE VIEW report_data.selection_medical_exam_information WITH (security_invoker=true,security_barrier=true) AS SELECT b."address",b."contact",b."created_at",b."created_by",b."email",b."exam_type",b."id",b."ips",b."operation_center_id",b."order_type",b."updated_at",b.company_id,b.operation_center_id AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=b.operation_center_id AND oc.company_id=b.company_id) AS report_center_name FROM public.selection_medical_exam_information b WHERE report_private.allowed(b.company_id, 'catalogos_seleccion_informacion_examenes_medicos', 'view') AND public.check_center_access(b.company_id,b.operation_center_id);
CREATE OR REPLACE VIEW report_data.employee_shift_assignments WITH (security_invoker=true,security_barrier=true) AS SELECT b."assignment_date",b."created_at",b."created_by",b."employee_id",b."id",b."operation_center_id",b."shift_id",b."source",b."updated_at",b.company_id,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,COALESCE(b.operation_center_id,w.operation_center_id) AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=COALESCE(b.operation_center_id,w.operation_center_id) AND oc.company_id=b.company_id) AS report_center_name FROM public.employee_shift_assignments b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND w.valid_from<=b.assignment_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.assignment_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'jornadas', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,COALESCE(b.operation_center_id,w.operation_center_id));
CREATE OR REPLACE VIEW report_data.employee_time_config WITH (security_invoker=true,security_barrier=true) AS SELECT b."created_at",b."created_by",b."cycle_start_date",b."employee_id",b."employment_cycle_id",b."end_date",b."id",b."is_active",b."mode",b."operation_center_id",b."shift_cycle_id",b."start_date",b."updated_at",b."work_schedule_id",b.company_id,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,COALESCE(b.operation_center_id,w.operation_center_id) AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=COALESCE(b.operation_center_id,w.operation_center_id) AND oc.company_id=b.company_id) AS report_center_name FROM public.employee_time_config b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND (b.employment_cycle_id IS NULL OR w.employment_cycle_id=b.employment_cycle_id) AND w.valid_from<=b.start_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.start_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'jornadas', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,COALESCE(b.operation_center_id,w.operation_center_id));
