CREATE OR REPLACE VIEW report_data.schedule_day_reviews WITH (security_invoker=true,security_barrier=true) AS SELECT b."employee_id",b."operation_center_id",b."reviewed_at",b."reviewed_by",b."reviewed_by_name",b."status",b."ticket_id",b."work_date",b.company_id,md5(row_to_json(b)::text) AS id,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,COALESCE(b.operation_center_id,w.operation_center_id) AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=COALESCE(b.operation_center_id,w.operation_center_id) AND oc.company_id=b.company_id) AS report_center_name FROM public.schedule_day_reviews b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND w.valid_from<=b.work_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.work_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'jornadas', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,COALESCE(b.operation_center_id,w.operation_center_id));
CREATE OR REPLACE VIEW report_data.time_clock_days WITH (security_invoker=true,security_barrier=true) AS SELECT b."break_minutes",b."created_at",b."early_leave_minutes",b."employee_id",b."employment_cycle_id",b."expected_end",b."expected_start",b."first_clock_in",b."id",b."last_clock_out",b."late_minutes",b."operation_center_id",b."schedule_name",b."scheduled_break_minutes",b."status",b."updated_at",b."work_date",b."worked_minutes",b.company_id,CASE WHEN b.expected_start IS NULL OR b.expected_end IS NULL THEN 0 ELSE greatest(0,round(extract(epoch FROM (b.expected_end-b.expected_start))/60)-b.scheduled_break_minutes) END AS scheduled_minutes,b.employee_id AS report_employee_id,concat_ws(' ',e.first_name,e.middle_name,e.last_name,e.second_last_name) AS report_employee_name,w.position_name AS report_position,(SELECT a.name FROM public.areas a WHERE a.id=w.area_id AND a.company_id=b.company_id) AS report_area_name,COALESCE(b.operation_center_id,w.operation_center_id) AS report_center_id,(SELECT oc.name FROM public.operation_centers oc WHERE oc.id=COALESCE(b.operation_center_id,w.operation_center_id) AND oc.company_id=b.company_id) AS report_center_name FROM public.time_clock_days b LEFT JOIN LATERAL (SELECT w.* FROM public.employee_work_info w WHERE w.employee_id=b.employee_id AND w.company_id=b.company_id AND (b.employment_cycle_id IS NULL OR w.employment_cycle_id=b.employment_cycle_id) AND w.valid_from<=b.work_date::date AND (w.valid_to IS NULL OR w.valid_to>=b.work_date::date) ORDER BY w.is_current DESC,w.valid_from DESC,w.id LIMIT 1) w ON true LEFT JOIN public.employees_v2 e ON e.id=b.employee_id AND e.company_id=b.company_id WHERE report_private.allowed(b.company_id, 'reloj_checador', 'view') AND (b.employee_id IS NULL OR public.has_employee_v2_access(b.employee_id)) AND public.check_center_access(b.company_id,COALESCE(b.operation_center_id,w.operation_center_id));
