('education_levels','Niveles educativos','catalogos_niveles_educativos','[{"key":"created_at","label":"Fecha de creación","type":"datetime"},{"key":"id","label":"Identificador","type":"text"},{"key":"is_active","label":"Activo","type":"boolean"},{"key":"name","label":"Nombre","type":"text"},{"key":"updated_at","label":"Última actualización","type":"datetime"}]'::jsonb,'created_at',NULL,NULL,NULL,'Niveles educativos: registros autorizados. Fecha predeterminada: created_at.'),
