('dotation_item_types','Tipos de dotación','catalogos_tipos_dotacion','[{"key":"category","label":"category","type":"text"},{"key":"code","label":"code","type":"text"},{"key":"created_at","label":"Fecha de creación","type":"datetime"},{"key":"created_by","label":"created by","type":"text"},{"key":"default_validity_months","label":"default validity months","type":"number"},{"key":"id","label":"Identificador","type":"text"},{"key":"is_active","label":"Activo","type":"boolean"},{"key":"name","label":"Nombre","type":"text"},{"key":"requires_size","label":"requires size","type":"boolean"},{"key":"updated_at","label":"Última actualización","type":"datetime"}]'::jsonb,'created_at',NULL,NULL,NULL,'Tipos de dotación: registros autorizados. Fecha predeterminada: created_at.'),
('exam_catalog','Catálogo de exámenes','examenes','[{"key":"code","label":"code","type":"text"},{"key":"created_at","label":"Fecha de creación","type":"datetime"},{"key":"created_by","label":"created by","type":"text"},{"key":"id","label":"Identificador","type":"text"},{"key":"is_active","label":"Activo","type":"boolean"},{"key":"name","label":"Nombre","type":"text"},{"key":"updated_at","label":"Última actualización","type":"datetime"}]'::jsonb,'created_at',NULL,NULL,NULL,'Catálogo de exámenes: registros autorizados. Fecha predeterminada: created_at.'),
('absence_days','Ausentismo diario sin duplicados','analitica_incapacidades','[{"key":"id","label":"Identificador","type":"text"},{"key":"report_employee_name","label":"Empleado","type":"text"},{"key":"report_center_name","label":"Centro de operación","type":"text"},{"key":"absence_date","label":"Fecha de ausencia","type":"date"},{"key":"absent_days","label":"Días de ausencia","type":"number","unit":"days"}]'::jsonb,'absence_date',NULL,'report_employee_id','report_center_id','Días calendario únicos por persona de incapacidades, permisos de día aprobados y vacaciones disfrutadas. Excluye permisos por horas, compensaciones y acumulaciones; respeta interrupciones y reanudaciones. Agrupar fecha por mes y sumar absent_days. No es tasa de ausentismo ni días de nómina: solicita definición y denominador si se pide una tasa.'),
('training_compliance','Cumplimiento de capacitación por periodo','capacitaciones_cumplimiento','[{"key":"id","label":"Identificador","type":"text"},{"key":"report_employee_name","label":"Empleado","type":"text"},{"key":"report_center_name","label":"Centro de operación","type":"text"},{"key":"course_id","label":"Curso (ID)","type":"text"},{"key":"course_name","label":"Curso","type":"text"},{"key":"period","label":"Periodo","type":"date"},{"key":"required_count","label":"Asignaciones requeridas","type":"number"},{"key":"completed_count","label":"Asignaciones completadas","type":"number"},{"key":"completion_percent","label":"Cumplimiento","type":"number","unit":"percent"},{"key":"completed_at","label":"Última finalización","type":"datetime"}]'::jsonb,'period',NULL,'report_employee_id','report_center_id','Una fila por empleado activo, curso aplicable y mes, centro actual. Reproduce cumplimiento: cursos activos publicado/borrador, periodo configurado o enlace del centro creado ese mes, completado por empleado o documento en cualquier fecha. Requiere seleccionar un mes. AVG(completion_percent) es cumplimiento; SUM(required_count/completed_count) son denominador/numerador. No es una fotografía histórica de la plantilla.');
GRANT SELECT ON ALL TABLES IN SCHEMA report_data TO authenticated;

UPDATE report_private.sources SET required_modules=ARRAY['incapacidades','permisos','vacaciones','empleados'] WHERE key='absence_days';
UPDATE report_private.sources SET required_modules=ARRAY['empleados','capacitaciones_biblioteca','capacitaciones_evidencias'] WHERE key='training_compliance';

CREATE FUNCTION report_private.store_run(c uuid,p jsonb,screen jsonb,q text,t text,provider_name text,parent uuid,result_data jsonb,reusable_context jsonb DEFAULT '[]') RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE run_id uuid; context_data jsonb:='[]';
BEGIN
 IF NOT report_private.allowed(c,'asistente_ia','view') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 IF jsonb_typeof(reusable_context) IS DISTINCT FROM 'array' OR jsonb_array_length(reusable_context)>12 OR EXISTS(SELECT 1 FROM jsonb_array_elements(reusable_context) ctx WHERE jsonb_typeof(ctx)<>'string' OR length(ctx#>>'{}')>2000) THEN RAISE EXCEPTION 'INVALID_PLAN: Contexto inválido'; END IF;
 context_data:=reusable_context;
 IF length(q) NOT BETWEEN 1 AND 2000 OR length(t)>160 THEN RAISE EXCEPTION 'INVALID_PLAN: Pregunta inválida'; END IF;
 IF parent IS NOT NULL THEN
  SELECT context||jsonb_build_array(question) INTO context_data FROM report_private.runs WHERE id=parent AND company_id=c AND user_id=auth.uid() AND fingerprint=report_private.fingerprint(c);
  IF context_data IS NULL THEN RAISE EXCEPTION 'STALE_ACCESS: Ejecuta de nuevo el reporte'; END IF;
  IF jsonb_array_length(context_data)>12 THEN RAISE EXCEPTION 'CONTEXT_LIMIT: Inicia un nuevo reporte'; END IF;
 END IF;
 INSERT INTO report_private.runs(company_id,user_id,parent_id,title,question,context,plan,filters,result,fingerprint,provider)
 VALUES(c,auth.uid(),parent,t,q,context_data,p,screen,result_data,report_private.fingerprint(c),provider_name) RETURNING id INTO run_id;
 RETURN run_id;
END $$;
REVOKE ALL ON FUNCTION report_private.store_run(uuid,jsonb,jsonb,text,text,text,uuid,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION report_private.store_run(uuid,jsonb,jsonb,text,text,text,uuid,jsonb,jsonb) TO authenticated;

CREATE FUNCTION public.create_ai_report(p_company_id uuid,p_plan jsonb,p_filters jsonb,p_question text,p_title text,p_provider text,p_parent_id uuid DEFAULT NULL,p_context jsonb DEFAULT '[]') RETURNS uuid
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' SET statement_timeout='25s' AS $$
DECLARE result_data jsonb; previous_data jsonb; previous_filters jsonb; start_day date; end_day date;
BEGIN
 result_data:=report_private.query(p_company_id,p_plan,p_filters);
 IF (p_plan->>'comparePrevious')::boolean THEN
  IF jsonb_array_length(p_plan->'metrics')=0 THEN RAISE EXCEPTION 'CLARIFICATION: Selecciona una métrica para comparar'; END IF;
  start_day:=(p_filters->>'startDate')::date;end_day:=(p_filters->>'endDate')::date;
  IF start_day IS NULL OR end_day IS NULL THEN RAISE EXCEPTION 'CLARIFICATION: Selecciona un periodo para comparar'; END IF;
  -- A complete calendar month compares with the preceding complete month.
  previous_filters:=p_filters||jsonb_build_object('startDate',CASE WHEN start_day=date_trunc('month',start_day)::date AND end_day=(start_day+interval '1 month'-interval '1 day')::date THEN (start_day-interval '1 month')::date ELSE start_day-(end_day-start_day+1) END,'endDate',start_day-1);
  previous_data:=report_private.query(p_company_id,p_plan,previous_filters);
  result_data:=result_data||jsonb_build_object('comparison',jsonb_build_object('startDate',previous_filters->>'startDate','endDate',previous_filters->>'endDate','rows',previous_data->'rows','totalRows',previous_data->'totalRows'));
 END IF;
 RETURN report_private.store_run(p_company_id,p_plan,p_filters,p_question,p_title,p_provider,p_parent_id,result_data,p_context);
END $$;

CREATE FUNCTION report_private.describe_filters(c uuid,p jsonb,screen jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE result_data jsonb:='[]';flt jsonb;src report_private.sources;label_text text;value_text text;rel jsonb;
BEGIN
 SELECT * INTO src FROM report_private.sources WHERE key=p->>'source';
 FOR flt IN SELECT * FROM jsonb_array_elements(p->'filters') LOOP
  SELECT f->>'label' INTO label_text FROM jsonb_array_elements(src.fields) f WHERE f->>'key'=flt->>'field';
  SELECT string_agg(CASE v WHEN 'true' THEN 'Sí' WHEN 'false' THEN 'No' ELSE v END,', ') INTO value_text FROM jsonb_array_elements_text(flt->'values') v;
  result_data:=result_data||jsonb_build_array(jsonb_build_object('label',coalesce(label_text,flt->>'field'),'value',CASE flt->>'op' WHEN 'eq' THEN 'Igual a ' WHEN 'neq' THEN 'Distinto de ' WHEN 'gt' THEN 'Mayor que ' WHEN 'gte' THEN 'Desde ' WHEN 'lt' THEN 'Menor que ' WHEN 'lte' THEN 'Hasta ' WHEN 'in' THEN 'Incluye ' WHEN 'contains' THEN 'Contiene ' WHEN 'is_null' THEN 'Sin valor' ELSE 'Con valor' END||coalesce(value_text,'')));
 END LOOP;
 IF screen->>'startDate' IS NOT NULL OR screen->>'endDate' IS NOT NULL THEN result_data:=result_data||jsonb_build_array(jsonb_build_object('label','Periodo','value',coalesce(screen->>'startDate','Sin inicio')||' a '||coalesce(screen->>'endDate','Sin fin')));END IF;
 SELECT string_agg(oc.name,', ' ORDER BY oc.name) INTO value_text FROM public.operation_centers oc WHERE oc.company_id=c AND oc.id IN (SELECT value::uuid FROM jsonb_array_elements_text(coalesce(screen->'centerIds','[]')));
 result_data:=result_data||jsonb_build_array(jsonb_build_object('label','Centros','value',coalesce(value_text,'Todos los centros autorizados')));
 FOR rel IN SELECT * FROM jsonb_array_elements(p->'related') LOOP
  SELECT label INTO label_text FROM report_private.sources WHERE key=rel->>'source';
  result_data:=result_data||jsonb_build_array(jsonb_build_object('label','Cruce','value',CASE WHEN rel->>'mode'='exists' THEN 'Con registros en ' ELSE 'Sin registros en ' END||label_text));
  result_data:=result_data||report_private.describe_filters(c,jsonb_build_object('source',rel->>'source','filters',rel->'filters','related','[]'::jsonb),'{}');
 END LOOP;
 RETURN result_data;
END $$;
REVOKE ALL ON FUNCTION report_private.describe_filters(uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.get_ai_report(p_company_id uuid,p_id uuid,p_offset integer DEFAULT 0,p_size integer DEFAULT 50,p_export boolean DEFAULT false,p_order text DEFAULT NULL,p_desc boolean DEFAULT false,p_search text DEFAULT '') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE run report_private.runs; source record; slice_data jsonb; indicators jsonb:='[]'; col jsonb; val numeric; total bigint; exported boolean:=true; series_data jsonb; sorted_sql text;
BEGIN
 IF NOT report_private.allowed(p_company_id,'asistente_ia','view') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 SELECT * INTO run FROM report_private.runs WHERE id=p_id AND company_id=p_company_id AND user_id=auth.uid();
 IF run.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND: Reporte no disponible'; END IF;
 IF run.fingerprint<>report_private.fingerprint(p_company_id) THEN RAISE EXCEPTION 'STALE_ACCESS: Tus permisos cambiaron. Ejecuta de nuevo el reporte'; END IF;
 FOR source IN SELECT s.* FROM report_private.sources s WHERE s.key IN (SELECT jsonb_array_elements_text(run.result->'sourceKeys')) LOOP
   IF NOT report_private.source_allowed(p_company_id,source.key,'view') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
   exported:=exported AND report_private.allowed(p_company_id,source.module,'export');
   exported:=exported AND report_private.source_allowed(p_company_id,source.key,'export');
   -- Restricted field permissions also apply to export, including filters/aggregates.
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(source.fields) f WHERE f ? 'permission' AND strpos(run.plan::text,f->>'key')>0 AND NOT report_private.allowed(p_company_id,f->>'permission','export')) THEN exported:=false; END IF;
 END LOOP;
 IF p_export AND NOT exported THEN RAISE EXCEPTION 'EXPORT_FORBIDDEN: No tienes permiso para exportar estas fuentes'; END IF;
 IF p_offset<0 OR p_size NOT BETWEEN 1 AND 1000 OR length(p_search)>200 THEN RAISE EXCEPTION 'INVALID_PAGE'; END IF;
 IF p_order IS NOT NULL THEN
   SELECT e INTO col FROM jsonb_array_elements(run.result->'columns') e WHERE e->>'key'=p_order;
   IF col IS NULL THEN RAISE EXCEPTION 'INVALID_ORDER'; END IF;
 END IF;
 sorted_sql:=CASE WHEN p_order IS NULL THEN 'ordinality' WHEN col->>'type'='number' THEN format('(v->>%L)::numeric %s NULLS LAST,ordinality',p_order,CASE WHEN p_desc THEN 'DESC' ELSE 'ASC' END) ELSE format('v->>%L %s NULLS LAST,ordinality',p_order,CASE WHEN p_desc THEN 'DESC' ELSE 'ASC' END) END;
 SELECT count(*) INTO total FROM jsonb_array_elements(run.result->'rows') v WHERE p_search='' OR strpos(lower(v::text),lower(p_search))>0;
 EXECUTE format('SELECT coalesce(jsonb_agg(v),''[]''::jsonb) FROM (SELECT v FROM jsonb_array_elements($1) WITH ORDINALITY e(v,ordinality) WHERE $2='''' OR strpos(lower(v::text),lower($2))>0 ORDER BY %s OFFSET $3 LIMIT $4) page',sorted_sql) INTO slice_data USING run.result->'rows',p_search,p_offset,p_size;
 FOR col IN SELECT * FROM jsonb_array_elements(run.result->'columns') LOOP
   IF col->>'type'='number' AND EXISTS(SELECT 1 FROM jsonb_array_elements(run.plan->'metrics') m WHERE m->>'key'=col->>'key') THEN
     -- Only additive aggregates are summed across groups; averages are never averaged again.
     IF EXISTS(SELECT 1 FROM jsonb_array_elements(run.plan->'metrics') m WHERE m->>'key'=col->>'key' AND m->>'op' IN ('sum','count')) OR (run.result->>'totalRows')::integer=1 THEN
       SELECT sum((r->>(col->>'key'))::numeric) INTO val FROM jsonb_array_elements(run.result->'rows') r;
       indicators:=indicators||jsonb_build_array(jsonb_build_object('label',col->>'label','value',coalesce(val,0),'unit',col->>'unit'));
     END IF;
   END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(v),'[]') INTO series_data FROM (SELECT v FROM jsonb_array_elements(run.result->'rows') v LIMIT 60) s;
 RETURN jsonb_build_object('version',2,'id',run.id,'title',run.title,'question',run.question,'createdAt',run.created_at,'provider',run.provider,'plan',run.plan,'filters',run.filters,'effectiveFilters',report_private.describe_filters(p_company_id,run.plan,run.filters),'context',run.context,
 'sources',(SELECT jsonb_agg(jsonb_build_object('key',s.key,'label',s.label)) FROM report_private.sources s WHERE s.key IN (SELECT jsonb_array_elements_text(run.result->'sourceKeys'))),
 'columns',run.result->'columns','rows',slice_data,'totalRows',total,'unfilteredRows',run.result->'totalRows','offset',p_offset,'pageSize',p_size,
 'summary',format('Se encontraron %s %s. %s Los indicadores corresponden al conjunto completo del reporte.',run.result->>'totalRows',CASE WHEN jsonb_array_length(run.plan->'metrics')>0 THEN 'grupos' ELSE 'registros' END,coalesce((SELECT string_agg((i->>'label')||': '||(i->>'value')||coalesce(' '||(i->>'unit'),'')||'.',' ') FROM jsonb_array_elements(indicators) i),'')),
 'indicators',indicators,'series',series_data,'seriesTruncated',(run.result->>'totalRows')::integer>60,'canExport',exported,'comparison',run.result->'comparison');
END $$;

CREATE FUNCTION public.ai_report_library(p_company_id uuid,p_action text DEFAULT 'list',p_id uuid DEFAULT NULL,p_title text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE run report_private.runs; favorite report_private.favorites; result_data jsonb;
BEGIN
 IF NOT report_private.allowed(p_company_id,'asistente_ia','view') THEN RAISE EXCEPTION 'FORBIDDEN: Asistente no habilitado'; END IF;
 IF p_action='favorite' THEN
   PERFORM public.get_ai_report(p_company_id,p_id);
   SELECT * INTO run FROM report_private.runs WHERE id=p_id AND company_id=p_company_id AND user_id=auth.uid();
   INSERT INTO report_private.favorites(company_id,user_id,title,question,context,filters) VALUES(p_company_id,auth.uid(),run.title,run.question,run.context,run.filters) ON CONFLICT(company_id,user_id,md5(question||context::text||filters::text)) DO UPDATE SET question=excluded.question RETURNING * INTO favorite;
   RETURN jsonb_build_object('id',favorite.id);
 ELSIF p_action='rename' THEN
   IF length(btrim(p_title)) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'INVALID_TITLE'; END IF;
   UPDATE report_private.favorites SET title=btrim(p_title) WHERE id=p_id AND company_id=p_company_id AND user_id=auth.uid(); RETURN '{}';
 ELSIF p_action='delete' THEN
   DELETE FROM report_private.favorites WHERE id=p_id AND company_id=p_company_id AND user_id=auth.uid(); RETURN '{}';
 ELSIF p_action='favorite_get' THEN
   SELECT * INTO favorite FROM report_private.favorites WHERE id=p_id AND company_id=p_company_id AND user_id=auth.uid();
   IF favorite.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
   RETURN jsonb_build_object('question',favorite.question,'context',favorite.context,'filters',favorite.filters,'title',favorite.title);
 ELSIF p_action<>'list' THEN RAISE EXCEPTION 'INVALID_ACTION';
 END IF;
 RETURN jsonb_build_object('version',2,
 'sources',(SELECT coalesce(jsonb_agg(jsonb_build_object('key',s.key,'label',s.label,'module',s.module,'fields',(SELECT jsonb_agg(f) FROM jsonb_array_elements(s.fields) f WHERE NOT f ? 'permission' OR report_private.allowed(p_company_id,f->>'permission','view')),'dateField',s.date_field,'endDateField',s.end_date_field,'employeeField',s.employee_field,'centerField',s.center_field,'description',s.description) ORDER BY s.label),'[]') FROM report_private.sources s WHERE report_private.source_allowed(p_company_id,s.key,'view')),
 'centers',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',oc.id,'name',oc.name) ORDER BY oc.name),'[]') FROM public.operation_centers oc WHERE oc.company_id=p_company_id AND public.check_center_access(p_company_id,oc.id)),
 'recent',(SELECT coalesce(jsonb_agg(v ORDER BY v->>'createdAt' DESC),'[]') FROM (SELECT jsonb_build_object('id',r.id,'title',r.title,'question',r.question,'createdAt',r.created_at,'filters',r.filters,'parentId',r.parent_id) v FROM report_private.runs r WHERE r.company_id=p_company_id AND r.user_id=auth.uid() ORDER BY r.created_at DESC LIMIT 40) t),
 'favorites',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'title',f.title,'question',f.question,'context',f.context,'filters',f.filters,'createdAt',f.created_at) ORDER BY f.created_at DESC),'[]') FROM report_private.favorites f WHERE f.company_id=p_company_id AND f.user_id=auth.uid()),
 'legacy',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'title',r.title,'question',r.title,'createdAt',r.last_message_at,'filters','{}'::jsonb,'legacy',true) ORDER BY r.last_message_at DESC),'[]') FROM (SELECT * FROM public.ai_chat_conversations WHERE user_id=auth.uid() AND company_id=p_company_id AND mode='data_analysis' ORDER BY last_message_at DESC LIMIT 20) r));
END $$;
REVOKE ALL ON FUNCTION public.create_ai_report(uuid,jsonb,jsonb,text,text,text,uuid,jsonb),public.get_ai_report(uuid,uuid,integer,integer,boolean,text,boolean,text),public.ai_report_library(uuid,text,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_ai_report(uuid,jsonb,jsonb,text,text,text,uuid,jsonb),public.get_ai_report(uuid,uuid,integer,integer,boolean,text,boolean,text),public.ai_report_library(uuid,text,uuid,text) TO authenticated;
